var ip = c.select('p.book-intro-index, p.cat-book-intro').first();
var intro = '';
if (ip) {
var clone = ip.clone();
clone.select('a').remove();
intro = cleanIntroText(clone.text());
}
var img = c.select('.media-left img, img').first();
var cover = img ? String(img.attr('abs:src') || img.attr('src') || '') : '';
if (!cover) cover = coverOf(url);
out.add(mkCard(name, author, '', '', intro, cover, url, ''));
}
return out;
}
function findPanel(doc, kw) {
var panels = doc.select('.panel');
for (var i = 0; i < panels.size(); i++) {
var hd = panels.get(i).select('.panel-heading').first();
if (hd && String(hd.text()).indexOf(kw) >= 0) return panels.get(i);
}
return null;
}
function tocLis(doc) {
